typedef unsigned char uint8;

class stringx {
  char data[8];
};

class color32 {
public:
  union {
    struct { uint8 r, g, b, a; } c;
    unsigned int rgba;
  };
  void set_alpha(uint8 arg) { c.a = arg; }
};

class StringList {
public:
  enum { MAX_STRING_SIZE = 150 };
  stringx data;
  float x;
  float y;
  float fall_speed[MAX_STRING_SIZE];
  float drift_speed[MAX_STRING_SIZE];
  int drift_max[MAX_STRING_SIZE];
  float delta_x[MAX_STRING_SIZE];
  float delta_y[MAX_STRING_SIZE];
};

class TextString {
protected:
  char pad0[52];
  bool override_alpha;
public:
  bool checkTime;
  float time;
  bool no_color;
  color32 color;
  virtual void Render(stringx* t, float x1, float y1);
  virtual void Render(stringx* t, float x1, float y1, float* xs, float* ys, bool random_text_fade = true);
};

class RandomText : public TextString {
protected:
  bool isRand;
  bool noFade;
  StringList rand_string;
};

class TrickBoxText : public RandomText {
protected:
  int numLines;
  int lineHeight;
  int width;
  int height;
  bool reverse;
  StringList box_strings[10];
  int box_str_count;
public:
  void Draw() __asm__("Draw__12TrickBoxText");
};

void TrickBoxText::Draw()
{
  if (!checkTime || time > 0)
  {
    for(int i = 0; i < box_str_count; i++)
    {
      StringList * tmp = &box_strings[i];

      if (override_alpha)
      {
        if (i == 0) color.set_alpha(255);
        else if (i == 1) color.set_alpha(127);
        else if (i == 2) color.set_alpha(63);
        else color.set_alpha(31);
      }

      if (isRand)
        Render(&tmp->data, tmp->x, tmp->y, tmp->delta_x, tmp->delta_y);
      else
        Render(&tmp->data, tmp->x, tmp->y);
    }
  }
}
